            C

    #include <stdio.h>

int main()  {
	while (1)
		printf("This loop will run forever.\n");
	return 0;
}

OutputThis loop will run forever.
This loop will run forever.
This loop will run forever.
...Using the do-while loop:
            C

    #include <stdio.h>

int main() {
	do {
		printf("This loop will run forever.");
	} while (1);

	return 0;
}

OutputThis loop will run forever.
This loop will run forever.
This loop will run forever.
...Nested LoopsNesting loops means placing one loop inside another. The inner loop runs fully for each iteration of the outer loop. This technique is helpful when you need to perform multiple iterations within each cycle of a larger loop, like when working with a two-dimensional array or performing tasks that require multiple levels of iteration.Example:
            C

    #include <stdio.h>

int main() {
    // Outer loop runs 3 times
    for (int i = 0; i < 3; i++) {

        // Inner loop runs 2 times for each
        // outer loop iteration
        for (int j = 0; j < 2; j++) {
            printf("i = %d, j = %d\n", i, j);
        }
    }
    return 0;
}

Outputi = 0, j = 0
i = 0, j = 1
i = 1, j = 0
i = 1, j = 1
i = 2, j = 0
i = 2, j = 1
Loop Control StatementsLoop control statements in C programming are used to change execution from its normal sequence.NameDescriptionbreakThe break statement is used to terminate the loop statement.continueWhen encountered, the continue statement skips the remaining body and jumps to the next iteration of the loop.gotogoto statement transfers the control to the labeled statement.Example:
            C

    #include <stdio.h>

int main() {
    for (int i = 0; i < 5; i++) {
        if (i == 3) {

            // Exit the loop when i equals 3
            break;  
        }
        printf("%d ", i);
    }
    printf("\n");

    for (int i = 0; i < 5; i++) {
        if (i == 3) {

            // Skip the current iteration
            // when i equals 3
            continue;  
        }
        printf("%d ", i);
    }
    printf("\n");
    for (int i = 0; i < 5; i++) {
        if (i == 3) {

            // Jump to the skip label when
            // i equals 3
            goto skip;
        }
        printf("%d ", i);
    }

skip:
    printf("\nJumped to the 'skip' label %s",
    "when i equals 3.");

    return 0;
}

Output0 1 2 
0 1 2 4 
0 1 2 
Jumped to the 'skip' label when i equals 3.
